<script setup lang="ts">
// AI 教练「我的统计」页：/ai/stats。
//
// 定位：给用户一个可回看的量化视角——和教练聊了多少、花了多少 token、常用哪些场景、
// 常问哪些题目，从而找到自己的学习优化方向（如「同一道题反复问却没 AC」就是信号）。
// 全部是聚合数字，不含消息正文；数据来自 GET /ai/stats（仅本人）。
//
// 图表：echarts 按项目惯例用函数式 ref 取 DOM（模板 ref 会收成数组，历史事故），
// 容器不随 v-if 销毁（空态整块替换图表区，图表只在有数据时初始化/销毁），
// 窗口 resize 时主动 layout。移动端（<800px）概览卡与图表单列堆叠，业务逻辑只有一份。

import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError } from "@/util/tips";
import { useBreakpoint } from "@/composables/useBreakpoint";
import echarts from "@/util/echarts";
import { handleGotoProblem } from "@/util/router";
import { useAiCoachStore } from "@/stores/aiCoach.ts";
import { GetAiStats } from "@/apis/ai-stats";
import type { AiStatsView } from "@/types/ai-stats";
import {
  AI_STATS_PALETTE,
  buildPieOption,
  buildTrendOption,
  fmtCount,
  getEntryPageTitle,
  getRefTypeTitle,
  getSceneTitle,
} from "./ai-stats-common";
import AiStatsDistList from "@/components/ai/AiStatsDistList.vue";
import AiEntryPageDist from "@/components/ai/AiEntryPageDist.vue";

const { globalProperties } = useCurrentInstance();
const router = useRouter();
const { isMobile } = useBreakpoint();
// 场景名以 /ai/scene 的服务端文案为准（store 有缓存，与浮窗/主界面同一份）
const store = useAiCoachStore();

const loading = ref(false);
const stats = ref<AiStatsView | null>(null);
const errorMessage = ref("");

/** 是否已有任何使用记录：决定空态引导还是统计内容 */
const hasUsage = computed(() => (stats.value?.totals.conversations ?? 0) > 0);

const load = async () => {
  loading.value = true;
  errorMessage.value = "";
  try {
    const res = await GetAiStats();
    if (res.code === 0) {
      stats.value = res.data as AiStatsView;
      // 图表容器在模板渲染后才存在（首次从空态切入时尤其如此），必须等一轮更新
      await nextTick();
      renderCharts();
    } else {
      errorMessage.value = `加载失败（错误码 ${res.code}）`;
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error("load ai stats failed:", err);
    errorMessage.value = "加载失败，请稍后重试";
    ShowTextTipsError(globalProperties, "加载教练统计失败");
  } finally {
    loading.value = false;
  }
};

// ── 图表 ──

const trendRef = ref<HTMLElement | null>(null);
const setTrendRef = (el: unknown) => {
  trendRef.value = (el as HTMLElement) ?? null;
};
const sceneRef = ref<HTMLElement | null>(null);
const setSceneRef = (el: unknown) => {
  sceneRef.value = (el as HTMLElement) ?? null;
};

let trendChart: ReturnType<typeof echarts.init> | null = null;
let sceneChart: ReturnType<typeof echarts.init> | null = null;

const renderCharts = () => {
  const data = stats.value;
  if (!data || data.trend.length === 0) {
    return;
  }
  const trendDom = trendRef.value;
  if (trendDom) {
    if (!trendChart) {
      trendChart = echarts.init(trendDom, null, { renderer: "canvas" });
    }
    trendChart.setOption(
      buildTrendOption(
        data.trend.map((d) => d.date.slice(5)),
        [
          { name: "消息", data: data.trend.map((d) => d.messages), color: AI_STATS_PALETTE[0] },
          { name: "会话", data: data.trend.map((d) => d.conversations), color: AI_STATS_PALETTE[1] },
        ],
        [{ name: "tokens", data: data.trend.map((d) => d.total_tokens), color: AI_STATS_PALETTE[3] }],
      ),
      true,
    );
  }
  const sceneDom = sceneRef.value;
  if (sceneDom && data.scenes.length > 0) {
    if (!sceneChart) {
      sceneChart = echarts.init(sceneDom, null, { renderer: "canvas" });
    }
    sceneChart.setOption(
      buildPieOption(
        data.scenes.map((s) => ({ name: getSceneTitle(store.sceneList, s.key), value: s.conversations })),
      ),
      true,
    );
  }
};

const handleResize = () => {
  trendChart?.resize();
  sceneChart?.resize();
};

onMounted(() => {
  void store.refreshSceneMeta();
  void load();
  window.addEventListener("resize", handleResize);
});

// 场景名以 /ai/scene 为准：元信息晚到时（比统计接口慢）重画一次饼图，
// 避免饼图停留在场景 key 而列表已是中文名的分裂状态
watch(
  () => store.sceneList,
  () => renderCharts(),
);

onBeforeUnmount(() => {
  window.removeEventListener("resize", handleResize);
  trendChart?.dispose();
  sceneChart?.dispose();
  trendChart = null;
  sceneChart = null;
});

// ── 展示辅助 ──

/** 场景 key → 展示名（分布列表与饼图共用） */
const sceneLabels = computed(() => {
  const map: Record<string, string> = {};
  for (const meta of store.sceneList) {
    map[meta.key] = meta.title;
  }
  return map;
});

const refTypeLabels = computed(() => {
  const map: Record<string, string> = {};
  for (const row of stats.value?.ref_types ?? []) {
    map[row.key] = getRefTypeTitle(row.key);
  }
  return map;
});

const entryPageLabels = computed(() => {
  const map: Record<string, string> = {};
  for (const row of stats.value?.entry_pages ?? []) {
    map[row.key] = getEntryPageTitle(row.key);
  }
  return map;
});

/** 常问题目：有 key 才能跳题目详情页（题目页按 key 查询），复用项目统一跳转 */
const gotoProblem = (key: string) => {
  if (!key) {
    return;
  }
  void handleGotoProblem(key);
};
</script>

<template>
  <div class="ai-stats">
    <t-loading :loading="loading" size="small">
      <!-- 错误态 -->
      <div v-if="errorMessage" class="stats-error">
        <t-alert theme="error" :message="errorMessage" />
        <t-button theme="primary" variant="outline" @click="load">重试</t-button>
      </div>

      <!-- 空态：还没有用过教练 -->
      <t-card v-else-if="stats && !hasUsage" class="stats-empty-card">
        <t-empty description="还没有和 AI 教练聊过" size="small" />
        <p class="stats-empty-tip">
          去题目页或提交页打开 AI 教练，聊过之后这里会展示你的对话量、token 消耗、常用场景与常问题目。
        </p>
        <t-button theme="primary" @click="router.push({ name: 'ai-conversation' })">前往「我的对话」</t-button>
      </t-card>

      <!-- 统计内容 -->
      <template v-else-if="stats && hasUsage">
        <!-- 概览卡 -->
        <div class="stats-cards">
          <t-card class="stats-card" :bordered="false">
            <div class="stats-card-label">会话</div>
            <div class="stats-card-value">{{ stats.totals.conversations }}</div>
            <div class="stats-card-sub">活跃 {{ stats.active_days }} 天</div>
          </t-card>
          <t-card class="stats-card" :bordered="false">
            <div class="stats-card-label">消息</div>
            <div class="stats-card-value">{{ fmtCount(stats.totals.messages) }}</div>
            <div class="stats-card-sub">与教练的问答消息</div>
          </t-card>
          <t-card class="stats-card" :bordered="false">
            <div class="stats-card-label">Token 消耗</div>
            <div class="stats-card-value">{{ fmtCount(stats.totals.total_tokens) }}</div>
            <div class="stats-card-sub">
              输入 {{ fmtCount(stats.totals.prompt_tokens) }} / 输出 {{ fmtCount(stats.totals.completion_tokens) }}
            </div>
          </t-card>
          <t-card class="stats-card" :bordered="false">
            <div class="stats-card-label">首次使用</div>
            <div class="stats-card-value stats-card-value-sm">{{ stats.first_use || "—" }}</div>
            <div class="stats-card-sub">开始使用 AI 教练的日期</div>
          </t-card>
        </div>

        <!-- 近 30 天趋势 -->
        <t-card title="近 30 天趋势" class="stats-block-card">
          <div :ref="setTrendRef" class="stats-chart" :class="{ 'stats-chart-mobile': isMobile }"></div>
        </t-card>

        <div class="stats-grid">
          <!-- 场景分布 -->
          <t-card title="场景分布" class="stats-block-card">
            <div v-if="stats.scenes.length > 0" :ref="setSceneRef" class="stats-chart" :class="{ 'stats-chart-mobile': isMobile }"></div>
            <div v-else class="stats-muted">暂无数据</div>
            <AiStatsDistList
              title=""
              :rows="stats.scenes"
              metric="conversations"
              :labels="sceneLabels"
              empty-text="还没有任何场景的使用记录"
            />
          </t-card>

          <!-- 引用对象分布 -->
          <t-card title="对话关联对象" class="stats-block-card">
            <AiStatsDistList
              title=""
              :rows="stats.ref_types"
              metric="conversations"
              :labels="refTypeLabels"
              empty-text="还没有关联具体对象的对话"
            />
          </t-card>
        </div>

        <!-- 打开页面分布：回答「用户从哪里问起」，也是判断是否还有页面没接入教练入口的依据；
             行内给出路由 name 与最常见的真实路径，点行看该页面的完整路径分布 -->
        <t-card title="打开教练时所在页面" class="stats-block-card">
          <AiEntryPageDist
            :rows="stats.entry_pages"
            :labels="entryPageLabels"
            empty-text="暂无记录（旧版本未上报打开页面）"
          />
        </t-card>

        <!-- 常问题目 -->
        <t-card title="常问题目" class="stats-block-card">
          <div v-if="stats.top_problems.length === 0" class="stats-muted">
            还没有针对具体题目的对话——去题目页点「AI 教练」开始吧。
          </div>
          <div v-else class="problem-rows">
            <div v-for="p in stats.top_problems" :key="p.problem_id" class="problem-row">
              <span
                class="problem-key"
                :class="{ 'is-link': !!p.problem_key }"
                @click="gotoProblem(p.problem_key)"
              >
                {{ p.problem_key || `#${p.problem_id}` }}
              </span>
              <span class="problem-title" :title="p.title || `题目 ${p.problem_id}`">
                {{ p.title || `题目 ${p.problem_id}` }}
              </span>
              <span class="problem-meta">{{ p.conversations }} 会话 · {{ fmtCount(p.messages) }} 消息</span>
              <span class="problem-meta">{{ fmtCount(p.total_tokens) }} tokens</span>
            </div>
          </div>
        </t-card>

        <div class="stats-grid">
          <!-- 模型分布 -->
          <t-card title="使用模型" class="stats-block-card">
            <AiStatsDistList
              title=""
              :rows="stats.models"
              metric="total_tokens"
              empty-text="暂无记录（历史消息未携带模型名）"
            />
          </t-card>

          <!-- 凭据来源 -->
          <t-card title="凭据来源" class="stats-block-card">
            <AiStatsDistList
              title=""
              :rows="stats.providers"
              metric="total_tokens"
              empty-text="暂无记录"
            />
          </t-card>
        </div>

        <!-- 工具调用 -->
        <t-card title="教练查询过的数据（工具调用）" class="stats-block-card">
          <AiStatsDistList
            title=""
            :rows="stats.tools"
            metric="messages"
            empty-text="对话中还没有触发过工具查询"
          />
        </t-card>
      </template>
    </t-loading>
  </div>
</template>

